SELECT  FROM crm_appointment a
INNER JOIN crm_customer c ON c.tenant_id=a.tenant_id AND c.id=a.customer_id
WHERE a.tenant_id=#{tenantId}
AND c.deleted=0



      AND a.institution_id IN #{institutionId}
      AND 1=0




AND a.customer_id=#{customerId}
AND a.institution_id=#{institutionId}
AND a.status=#{status}
ORDER BY a.id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM crm_appointment a
INNER JOIN crm_customer c ON c.tenant_id=a.tenant_id AND c.id=a.customer_id
WHERE a.tenant_id=#{tenantId}
AND c.deleted=0



      AND a.institution_id IN #{institutionId}
      AND 1=0




AND a.customer_id=#{customerId}
AND a.institution_id=#{institutionId}
AND a.status=#{status}

SELECT DISTINCT 
FROM crm_redemption r
INNER JOIN crm_customer c ON c.tenant_id=r.tenant_id AND c.id=r.customer_id

  INNER JOIN crm_redemption_line l ON l.tenant_id=r.tenant_id
    AND l.redemption_id=r.id AND l.project_id=#{projectId}

WHERE r.tenant_id=#{tenantId}
AND c.deleted=0



      AND r.institution_id IN #{institutionId}
      AND 1=0




AND r.customer_id=#{customerId}
AND r.institution_id=#{institutionId}
AND r.status=#{status}
ORDER BY r.id DESC LIMIT #{size} OFFSET #{offset}

